insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-273', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'Adding a suitable catalyst to a reacting mixture', '["increases the rate by opening a lower-energy path","is consumed as a stoichiometric reactant","alters the value of $\\Delta H$ for the net reaction","can change a first-order law into Faraday''s law"]'::jsonb, 0, 'The catalyst is regenerated. It does not change the thermodynamics of the net reaction, only how fast equilibrium is reached.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'rate-factors') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
