insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-275', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'Ionic reactions in water are often much faster than reactions of covalent organic molecules because', '["ions need little bond-breaking to meet, whereas covalent bonds must usually be broken and remade","ions have no charge","organic molecules never collide","water cannot solvate ions"]'::jsonb, 0, 'The nature of the reactants matters: many aqueous ion combinations are essentially encounter-controlled, unlike typical covalent substitutions.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'rate-factors') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
