insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-276', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'Raising the pressure of a gaseous reactant (at fixed $T$) often increases the rate because', '["the concentration of that gas rises, and rate laws depend on concentration","pressure changes the Faraday constant","gases become solids above 2 atm","molecularity becomes zero"]'::jsonb, 0, 'For an ideal gas, concentration $= p/RT$. A higher partial pressure therefore feeds the rate law.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'rate-factors') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
