insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-278', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'A catalyst that accelerates both the forward and reverse steps equally will', '["leave $\\Delta H$ and the equilibrium constant unchanged","make $\\Delta H$ more negative","shift $K$ toward products at every temperature","destroy the reverse reaction"]'::jsonb, 0, 'Equilibrium composition is fixed by $\Delta G^\circ$. The catalyst shortens the time needed to reach that same composition.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'rate-factors') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
