insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-279', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'A photochemical reaction differs from an ordinary thermal reaction in that its rate', '["depends on the intensity (and wavelength) of the absorbed light","is completely independent of photon energy","can never involve a chain of radicals","always follows Faraday''s second law"]'::jsonb, 0, 'Absorption of a suitable photon supplies the activation; brighter light of the right colour produces more excited molecules per second.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'rate-factors') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
