insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-283', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'An effective collision is one that', '["has both sufficient energy and the correct geometry, and therefore leads to product","occurs at the wall of the vessel only","involves the solvent but never the solute","always produces light"]'::jsonb, 0, 'Collision theory writes rate ∝ (collision frequency) × (energy factor) × (steric factor).', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'collision-qual') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
